                    "INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
                            + " VALUES (?, ?, ?, ?, ?, ?)",
                    ((Number) inv.get("id")).longValue(),
                    ((Number) inv.get("projectId")).longValue(),
